// รับไฟล์จาก webhook - multipart (field=file) หรือ raw binary
const input = $input.first();
const binaryKeys = input.binary ? Object.keys(input.binary) : [];
const body = input.json?.body || {};

if (!binaryKeys.length) {
  const hint = body.file && typeof body.file === 'string' && body.file.includes('/')
    ? ' (body.file เป็น path ไม่ใช่ไฟล์จริง - ตรวจสอบว่า Bruno/Client ส่งไฟล์เป็น File ไม่ใช่ Text)'
    : '';
  throw new Error('ไม่พบไฟล์ ส่ง multipart field=file หรือ raw binary' + hint);
}

const fileKey = binaryKeys.find(k => /^(file|data|document|image)(\d*)$/.test(k)) || binaryKeys[0];
const binaryData = input.binary[fileKey];
const filename = binaryData.fileName || binaryData.file_name || 'document';

return [{
  json: { filename, source_field: fileKey },
  binary: { data: binaryData }
}];

// ดึงทุก element ไม่ตัดทิ้ง - รวม text จากทุก field ที่มี
const allItems = $input.all();
const metadata = $('Prepare File').first().json;
const prepBinary = $('Prepare File').first().binary?.data;

const elements = allItems.length > 1 ? allItems.map(i => i.json) : (() => { const r = allItems[0]?.json; return Array.isArray(r) ? r : (r?.elements || [r]); })();
const cleanElements = elements
  .filter(el => el && typeof el === 'object')
  .map((el, i) => {
    const text = (el.text || el.content || el.value || '').trim();
    const tableHtml = el.metadata?.text_as_html;
    return {
      idx: i + 1,
      type: el.type || 'Unknown',
      text: text || (tableHtml ? '[Table]' : ''),
      page: el.metadata?.page_number,
      ...(tableHtml && { table_html: tableHtml })
    };
  })
  .filter(el => el.text || el.table_html);

if (!cleanElements.length) throw new Error('OCR ไม่พบข้อความในไฟล์');

const rawText = cleanElements.map(e => e.table_html ? e.table_html : e.text).filter(Boolean).join('\n\n');
const fullContent = cleanElements.map(e => `[${e.idx}] ${e.type} (p${e.page || '?'}):\n${(e.table_html || e.text || '').trim()}`).join('\n---\n');

return [{
  json: {
    filename: metadata.filename,
    elements: cleanElements,
    raw_text: rawText,
    full_content: fullContent,
    word_count: rawText.split(/\s+/).filter(w => w).length,
    element_count: cleanElements.length,
    image_base64: prepBinary?.data || null,
    mime_type: prepBinary?.mimeType || (metadata.filename?.match(/\.(png|webp)$/i) ? 'image/png' : 'image/jpeg')
  }
}];

// รวมผลลัพธ์ OCR + AI structure + elements
const ocrData = $('Format OCR Text').first().json;
const aiResponse = $input.first().json;

let structured = null;
const content = aiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
if (content) {
  const parseJson = (s) => { if (!s || typeof s !== 'string') return null; try { return JSON.parse(s); } catch (_) { return null; } };
  let toParse = content.trim();
  const codeBlock = toParse.match(/```(?:json)?\s*([\s\S]*?)(?:```|$)/);
  if (codeBlock && codeBlock[1]) toParse = codeBlock[1].trim();
  const braceMatch = toParse.match(/(\{[\s\S]*)/);
  if (braceMatch) toParse = braceMatch[1];
  structured = parseJson(toParse);
  if (!structured && toParse.includes('{')) {
    let fixed = toParse;
    let escape = false, inStr = false;
    for (let i = 0; i < toParse.length; i++) {
      const c = toParse[i];
      if (escape) { escape = false; continue; }
      if (c === '\\') { escape = true; continue; }
      if (c === '"') inStr = !inStr;
    }
    if (inStr) fixed += '"';
    const stack = [];
    for (const c of fixed) { if (c === '{') stack.push('}'); else if (c === '[') stack.push(']'); else if (c === '}' || c === ']') stack.pop(); }
    fixed += stack.reverse().join('');
    structured = parseJson(fixed);
  }
  if (!structured) structured = { raw_parsed: content };
}

return [{
  json: {
    success: true,
    filename: ocrData.filename,
    raw_text: ocrData.raw_text,
    full_content: ocrData.full_content,
    word_count: ocrData.word_count,
    element_count: ocrData.element_count,
    elements: ocrData.elements,
    structured
  }
}];

// รวม structured + summary
const prev = $('Format Response').first().json;
const summaryRes = $input.first().json;
const summary = summaryRes.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';

return [{ json: { ...prev, summary } }];
